{
  "name": "UDP数据采样进程",
  "name_en": "UDP Sampler Process",
  "manufacturer": "",
  "description": "这是一个非实体的软件组件，用于从 SPIDR 接收 Timepix 相关的 UDP 数据包，进行基础预处理、缓冲、转发以及可选的原始数据落盘，通常用于实验数据采集流水线中的前端接收环节。",
  "description_en": "This is a non-physical software component that receives UDP packets from SPIDR carrying Timepix-related data, performs basic preprocessing, buffering, forwarding, and optional raw-data recording to disk. It is typically used as a front-end acquisition stage in an experimental data-processing pipeline.",
  "actions": [
    {
      "action_name": "auto-init_new_process",
      "description": "初始化新进程中的连接与内部变量，并建立与后续数据处理模块的通信。",
      "description_en": "Initialize connections and internal variables in the new process, and create communication with the downstream packet processor."
    },
    {
      "action_name": "auto-create_socket_connection",
      "description": "创建到 SPIDR 的 UDP 套接字连接，用于接收实验数据包。",
      "description_en": "Create a UDP socket connection to SPIDR for receiving experimental data packets."
    },
    {
      "action_name": "auto-get_useful_packets",
      "description": "从接收到的数据包中提取有用内容和报头，供后续处理使用。",
      "description_en": "Extract useful content and headers from a received packet for downstream processing."
    },
    {
      "action_name": "auto-enable",
      "description": "获取或设置数据处理使能状态。",
      "description_en": "Get or set the processing enabled state."
    },
    {
      "action_name": "auto-record",
      "description": "获取或设置原始数据写入磁盘的记录状态。",
      "description_en": "Get or set the raw-data recording state for saving to disk."
    },
    {
      "action_name": "auto-close_file",
      "description": "获取或设置原始数据文件关闭请求。",
      "description_en": "Get or set the raw-data file close request."
    },
    {
      "action_name": "auto-outfile_name",
      "description": "获取或设置输出文件名。",
      "description_en": "Get or set the output file name."
    },
    {
      "action_name": "auto-pre_run",
      "description": "在子进程正式运行前完成仅在新进程中可用的初始化准备。",
      "description_en": "Perform initialization steps before execution that should only be available inside the child process."
    },
    {
      "action_name": "auto-post_run",
      "description": "在运行结束或超时后执行收尾处理，例如整理缓冲数据并处理文件关闭逻辑。",
      "description_en": "Perform post-run cleanup after execution or timeout, such as finalizing buffered data and handling file-closing logic."
    },
    {
      "action_name": "auto-run",
      "description": "启动采样进程的主循环，持续接收 UDP 数据、筛选有效包、打包缓冲并转发或记录数据。",
      "description_en": "Run the main acquisition loop that continuously receives UDP data, filters useful packets, buffers them, and forwards or records the data."
    }
  ],
  "tag_hints": [
    "UDP data acquisition",
    "SPIDR packet receiver",
    "Timepix data pipeline",
    "raw data recording",
    "multiprocessing worker",
    "packet preprocessing",
    "socket-based acquisition"
  ]
}

